import {getComponentDescriptor,type ComponentContainerDescriptor} from "./componentDescriptorRegistry";
export type ComponentRecord=Record<string,unknown>;
export interface ComponentVisit{component:ComponentRecord;path:string;depth:number;datasetName:string;parent:unknown[]|ComponentRecord;index:number|string;containerPath:string;container?:ComponentContainerDescriptor;}
export const isComponentRecord=(value:unknown):value is ComponentRecord=>Boolean(value)&&typeof value==="object"&&!Array.isArray(value)&&typeof (value as ComponentRecord).type==="string";
export function visitSpecificationComponents(specification:unknown,visitor:(visit:ComponentVisit)=>boolean|void):void{if(!specification||typeof specification!=="object"||Array.isArray(specification))return;const root=specification as ComponentRecord;const visitArray=(items:unknown[],path:string,depth:number,datasetName:string,container?:ComponentContainerDescriptor):boolean=>{for(let index=0;index<items.length;index+=1){const component=items[index];if(!isComponentRecord(component))continue;const effective=typeof component.dataset==="string"?component.dataset:datasetName;const current={component,path:`${path}/${index}`,depth,datasetName:effective,parent:items,index,containerPath:path,container};if(visitor(current)===true)return true;if(visitChildren(current))return true;}return false;};const visitChildren=(current:ComponentVisit):boolean=>{const descriptor=getComponentDescriptor(String(current.component.type));for(const container of descriptor?.containers??[]){if(container.kind==="array"){const children=current.component[container.property];if(Array.isArray(children)&&visitArray(children,`${current.path}/${container.property}`,current.depth+1,current.datasetName,container))return true;}else if(container.kind==="single"){const child=current.component[container.property];if(isComponentRecord(child)){const next={component:child,path:`${current.path}/${container.property}`,depth:current.depth+1,datasetName:typeof child.dataset==="string"?child.dataset:current.datasetName,parent:current.component,index:container.property,containerPath:current.path,container};if(visitor(next)===true||visitChildren(next))return true;}}else if(container.kind==="tabs"&&Array.isArray(current.component.tabs)){const property=container.property.split(".")[1];for(let tabIndex=0;tabIndex<current.component.tabs.length;tabIndex+=1){const tab=current.component.tabs[tabIndex];if(tab&&typeof tab==="object"&&!Array.isArray(tab)){const children=(tab as ComponentRecord)[property];if(Array.isArray(children)&&visitArray(children,`${current.path}/tabs/${tabIndex}/${property}`,current.depth+1,current.datasetName,container))return true;}}}else if(container.kind==="accordion"&&Array.isArray(current.component.items)){const property=container.property.split(".")[1];for(let itemIndex=0;itemIndex<current.component.items.length;itemIndex+=1){const item=current.component.items[itemIndex];if(item&&typeof item==="object"&&!Array.isArray(item)){const children=(item as ComponentRecord)[property];if(Array.isArray(children)&&visitArray(children,`${current.path}/items/${itemIndex}/${property}`,current.depth+1,current.datasetName,container))return true;}}}}return false;};for(const key of ["toolbar","leftPanel","components","rightPanel"]){const items=root[key];if(Array.isArray(items)&&visitArray(items,`/${key}`,0,"powerbi"))return;}}
