    const visiting = new Set<string>(); const visited = new Set<string>(); const visit = (key: string): boolean => { if (visiting.has(key)) return true; if (visited.has(key)) return false; visiting.add(key); if ([...(dependencies.get(key) ?? [])].some(visit)) return true; visiting.delete(key); visited.add(key); return false; };
    keys.forEach(key => { if (visit(key)) messages.push({ level:"error", path:"fields", message:`Cyclic calculated field dependency includes ${key}.` }); });
    const available = new Set([...base, ...keys]); const metricKeys = new Set<string>();const aggregations=new Set(["count","countWhere","sum","sumWhere","avg","avgWhere","min","max","distinctCount","ratio","percentOfTotal"]);
