export type DiagnosticSeverity = "error" | "warning" | "info";
export type DiagnosticCode = "INVALID_JSON" | "MULTIPLE_JSON_OBJECTS" | "TRUNCATED_JSON" | "UNSUPPORTED_VERSION" | "UNKNOWN_PROPERTY" | "UNKNOWN_COMPONENT_TYPE" | "MISSING_REQUIRED_PROPERTY" | "INVALID_PROPERTY_TYPE" | "INVALID_ENUM_VALUE" | "DUPLICATE_COMPONENT_ID" | "UNKNOWN_COMPONENT_TARGET" | "UNKNOWN_FIELD" | "AMBIGUOUS_FIELD" | "FIELD_TYPE_MISMATCH" | "UNKNOWN_DATASET" | "UNKNOWN_DATASET_FIELD" | "NON_NUMERIC_DATASET_FIELD" | "UNFILTERABLE_GENERATED_FIELD" | "DATASET_CYCLE" | "INVALID_DATASET_DEFINITION" | "UNKNOWN_DEFINITION" | "DEFINITION_CYCLE" | "INVALID_INTERACTION" | "DEPRECATED_PROPERTY" | "UNSUPPORTED_ADVANCED_OPTION" | "REPAIR_APPLIED" | `MAP_${string}` | `SVG_${string}`;
export interface Diagnostic { code:DiagnosticCode;severity:DiagnosticSeverity;path:string;componentId?:string;message:string;received?:unknown;suggestions?:string[];autoFixAvailable?:boolean; }

function distance(left:string,right:string):number{const a=left.toLowerCase(),b=right.toLowerCase();const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i+=1){let diagonal=row[0];row[0]=i;for(let j=1;j<=b.length;j+=1){const previous=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,diagonal+(a[i-1]===b[j-1]?0:1));diagonal=previous;}}return row[b.length];}
export function closestMatches(received:string,candidates:Iterable<string>,limit=3):string[]{return Array.from(new Set(candidates)).map(value=>({value,score:distance(received,value)})).filter(item=>item.score<=Math.max(2,Math.floor(received.length*.4))).sort((a,b)=>a.score-b.score||a.value.localeCompare(b.value)).slice(0,limit).map(item=>item.value);}
export function diagnosticsToStrings(diagnostics:Diagnostic[]):string[]{return diagnostics.map(item=>`${item.path || "/"} [${item.code}] ${item.message}${item.suggestions?.length?` Did you mean ${item.suggestions.join(", ")}?`:""}`);}
