import DOMPurify from "dompurify";
import type { SvgBindingContext } from "../components/svg/svgBindings";
import { renderSvgTemplate } from "../components/svg/svgBindings";
import { safeSvgIdentifier } from "../components/svg/svgIdIsolation";
import { SVG_ELEMENT_TYPES, SVG_LIMITS } from "../components/svg/svgTypes";
import { compileBoundSvgMotion } from "./sanitizeSvgMotion";
import { fitSvgViewport, parseSvgDocument, svgNamespace } from "./svgMarkupDocument";

export interface SanitizedSvg { svg: string; warnings: string[]; elementCount: number; animatedElementCount: number; pathCount: number; idMap: Map<string, string>; motionCss?: string; }
const elementNames = ["svg", ...SVG_ELEMENT_TYPES];
const elements = new Set<string>(elementNames.map(name => name.toLowerCase()));
const attributes = new Set(["id", "class", "data-hp-mermaid-node", "viewbox", "width", "height", "preserveaspectratio", "role", "aria-label", "aria-labelledby", "aria-describedby", "focusable", "tabindex", "opacity", "transform", "fill", "fill-opacity", "fill-rule", "stroke", "stroke-width", "stroke-opacity", "stroke-dasharray", "stroke-dashoffset", "stroke-linecap", "stroke-linejoin", "stroke-miterlimit", "vector-effect", "paint-order", "clip-path", "mask", "filter", "marker-start", "marker-mid", "marker-end", "visibility", "pointer-events", "x", "y", "x1", "y1", "x2", "y2", "cx", "cy", "r", "rx", "ry", "dx", "dy", "d", "points", "pathlength", "text-anchor", "dominant-baseline", "font-family", "font-size", "font-weight", "font-style", "letter-spacing", "fx", "fy", "offset", "stop-color", "stop-opacity", "gradientunits", "gradienttransform", "spreadmethod", "markerwidth", "markerheight", "refx", "refy", "orient", "markerunits", "xmlns"]);
const referenceAttributes = new Set(["fill", "stroke", "clip-path", "mask", "filter", "marker-start", "marker-mid", "marker-end", "aria-labelledby", "aria-describedby"]);
const escapeXml = (value: string) => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
export function resolveSvgMarkupTemplates(markup: string, context: SvgBindingContext): string {
    if (/<\s*\/?\s*\{\{|\{\{[^}]+\}\}\s*=/.test(markup)) throw new Error("SVG templates cannot create element or attribute names.");
    if (/\bd\s*=\s*["'][^"']*\{\{/i.test(markup)) throw new Error("Raw SVG path data cannot be injected from fields.");
    return markup.replace(/\{\{\s*([A-Za-z_$][\w$.-]*)\s*\}\}/g, match => escapeXml(renderSvgTemplate(match, context)));
}

export function sanitizeSvg(input: string, namespace: string, options: {
    mermaidNodeIds?: ReadonlySet<string>;
    mode?: "sanitized" | "trusted";
    bound?: { maxElements: number; maxAnimations: number };
} = {}): SanitizedSvg {
    const warnings: string[] = []; let elementCount = 0, animatedElementCount = 0, pathCount = 0;
    const ids = new Map<string, string>(), motionCss: string[] = [];
    const reject = (message: string): SanitizedSvg => ({ svg: "", warnings: [message], elementCount, animatedElementCount, pathCount, idMap: ids });
    const bound = options.bound;
    if (!bound && options.mode === "trusted") return { ...reject("Trusted SVG must be rendered in an isolated document; browser and host policies still apply."), svg: input };
    if (input.length > SVG_LIMITS.maxMarkupLength) return reject("Raw SVG exceeded the 250,000 character limit.");
    if (bound && /<!DOCTYPE\b/i.test(input)) return reject("SVG document type declarations are unsupported.");
    const root = parseSvgDocument(input);
    if (!root || bound && (root.localName !== "svg" || root.namespaceURI !== svgNamespace || root.prefix)) {
        return reject("Raw SVG could not be parsed as a single SVG document.");
    }
    if (bound && !fitSvgViewport(root)) return reject("The SVG needs a valid viewBox or positive width and height in pixels.");
    const maxElements = bound ? Math.min(bound.maxElements, SVG_LIMITS.maxElementsPerComponent) : SVG_LIMITS.maxElementsPerComponent;
    const maxAnimations = bound ? Math.min(bound.maxAnimations, SVG_LIMITS.maxAnimatedPerComponent) : 0;
    let limitError: string | undefined;
    const visit = (element: Element, depth: number): void => {
        const tag = element.localName.toLowerCase();
        if (limitError) return;
        if (bound && (element.namespaceURI !== svgNamespace || element.prefix)) {
            warnings.push("Blocked content outside the SVG namespace.");
            element.remove();
            return;
        }
        if (bound && tag === "animate") {
            elementCount++;
            if (elementCount > maxElements) limitError = `Raw SVG exceeded ${maxElements} elements.`;
            const target = element.parentElement;
            const css = depth <= SVG_LIMITS.maxDepth && target && !target.hasAttribute("data-hp-svg-motion") && animatedElementCount < maxAnimations
                ? compileBoundSvgMotion(element, namespace, animatedElementCount) : undefined;
            if (css && target) {
                target.setAttribute("data-hp-svg-motion", String(animatedElementCount++));
                motionCss.push(css);
            } else if (maxAnimations > 0) warnings.push("Blocked unsupported SVG animation or animation exceeding the limit.");
            element.remove();
            return;
        }
        if (!elements.has(tag) || bound && !elementNames.includes(element.localName)) { warnings.push(`Blocked SVG element: ${tag}.`); element.remove(); return; }
        elementCount++;
        if (bound && elementCount > maxElements) { limitError = `Raw SVG exceeded ${maxElements} elements.`; return; }
        if (tag === "path") {
            pathCount++;
            const d = element.getAttribute("d");
            if (d && d.length > SVG_LIMITS.maxPathLength) {
                const message = "Blocked SVG path exceeding the path length limit.";
                if (bound) { limitError = message; return; }
                warnings.push(message);
                element.removeAttribute("d");
            }
        }
        if (depth > SVG_LIMITS.maxDepth) {
            const message = `Blocked SVG content deeper than ${SVG_LIMITS.maxDepth} levels.`;
            if (bound) { limitError = message; return; }
            warnings.push(message);
            element.remove();
            return;
        }
        for (const attribute of Array.from(element.attributes)) {
            const name = attribute.name.toLowerCase(), value = attribute.value.trim();
            if (name.startsWith("on") || name === "style" || name === "href" || name === "xlink:href" || name === "src" || name === "srcset" || name === "formaction" || !attributes.has(name)) { warnings.push(`Blocked SVG attribute: ${attribute.name}.`); element.removeAttribute(attribute.name); continue; }
            if (name === "xmlns" && value === "http://www.w3.org/2000/svg") continue;
            if (/javascript\s*:|data\s*:|blob\s*:|https?\s*:|\/\//i.test(value)) { warnings.push(`Blocked external SVG value on ${attribute.name}.`); element.removeAttribute(attribute.name); continue; }
            if (name === "id") {
                if (attribute.name !== name || !/^[A-Za-z_][A-Za-z0-9_.:-]{0,127}$/.test(value) || ids.has(value)) { warnings.push(`Blocked invalid or duplicate SVG ID: ${value}.`); element.removeAttribute(attribute.name); }
                else { ids.set(value, `${namespace}-${safeSvgIdentifier(value)}`); element.setAttribute("id", value); }
            }
            if ((referenceAttributes.has(name) || bound && name === "d") && attribute.name !== name) element.removeAttribute(attribute.name);
            if (name === "class" && !/^[A-Za-z0-9_ -]*$/.test(value)) { warnings.push("Blocked unsafe SVG class value."); element.removeAttribute(attribute.name); }
            if (name === "data-hp-mermaid-node" && (!/^[A-Za-z][A-Za-z0-9_-]{0,127}$/.test(value) || !options.mermaidNodeIds?.has(value))) { warnings.push("Blocked uncontrolled Mermaid node identity."); element.removeAttribute(attribute.name); }
        }
        Array.from(element.children).forEach(child => visit(child, depth + 1));
    };
    visit(root, 0);
    if (limitError || elementCount > maxElements) return reject(limitError ?? `Raw SVG exceeded ${maxElements} elements.`);
    if (bound && !Array.from(root.querySelectorAll("path,rect,circle,ellipse,line,polyline,polygon,text")).some(element => !element.closest("defs,clipPath,mask,marker"))) {
        return reject("The SVG has no supported drawing elements.");
    }
    for (const element of [root, ...Array.from(root.querySelectorAll("*"))]) {
        const originalId = element.getAttribute("id"); if (originalId && ids.has(originalId)) element.setAttribute("id", ids.get(originalId)!);
        for (const attributeName of referenceAttributes) {
            const value = element.getAttribute(attributeName)?.trim(); if (!value) continue;
            if (attributeName.startsWith("aria-")) {
                const resolved = value.split(/\s+/).map(token => ids.get(token.replace(/^#/, ""))).filter(Boolean);
                if (resolved.length) element.setAttribute(attributeName, resolved.join(" "));
                else element.removeAttribute(attributeName);
                continue;
            }
            const url = /^url\(\s*(["']?)#([A-Za-z_][\w:.-]*)\1\s*\)$/i.exec(value);
            if (url) { const id = ids.get(url[2]); if (id) element.setAttribute(attributeName, `url(#${id})`); else { warnings.push(`Blocked unknown SVG reference #${url[2]}.`); element.removeAttribute(attributeName); } }
            else if (/url\s*\(|\\|\/\*/i.test(value)) { warnings.push(`Blocked malformed SVG reference on ${attributeName}.`); element.removeAttribute(attributeName); }
        }
    }
    root.setAttribute("xmlns", "http://www.w3.org/2000/svg");
    const serialized = new XMLSerializer().serializeToString(root);
    const svg = DOMPurify.sanitize(serialized, { USE_PROFILES: { svg: true, svgFilters: false }, ADD_TAGS: [...elementNames], ADD_ATTR: [...attributes, ...(motionCss.length ? ["data-hp-svg-motion"] : [])], FORBID_TAGS: ["script", "foreignObject", "iframe", "object", "embed", "image", "use", "audio", "video", "canvas", "style", "a", "switch", "set", "discard"], FORBID_ATTR: ["style", "href", "xlink:href", "src", "srcset"], ALLOW_DATA_ATTR: false, RETURN_TRUSTED_TYPE: false }) as string;
    // With an SVG-only profile DOMPurify also drops its own HTML parsing wrapper.
    if (DOMPurify.removed.some(entry => "attribute" in entry || entry.element.nodeName !== "BODY")) {
        warnings.push("Final SVG sanitization removed unsafe content.");
    }
    return { svg, warnings: Array.from(new Set(warnings)), elementCount, animatedElementCount, pathCount, idMap: ids, motionCss: motionCss.join("\n") };
}
