const categories = [["source", "Data"], ["renderer", "Style"], ["labels", "Labels"], ["popup", "Popup"], ["visibility", "Filter"], ["effects", "Effects"], ["interaction", "Interactions"], ["performance", "Advanced"]] as const;
export function MapPropertyCategories({ value, onChange, supported, unsupportedReason }: { value: string; onChange: (value: string) => void; supported: (value: string) => boolean; unsupportedReason?: string }) {
    const selected = ["join", "legend", "tooltip", "diagnostics"].includes(value) ? "performance" : value;
    return <><nav class="hp-map-category-tabs" aria-label="Layer categories">{categories.map(([id, label]) => <button type="button" aria-pressed={selected === id} disabled={!supported(id)} title={!supported(id) ? unsupportedReason ?? "Unavailable for this source type" : undefined} onClick={() => onChange(id)}>{label}</button>)}</nav>{selected === "performance" && <label class="hp-map-advanced-category"><span>Advanced setting</span><select aria-label="Advanced layer setting" value={value} onChange={event => onChange(event.currentTarget.value)}>{[["performance", "Performance"], ["join", "Data relationship"], ["legend", "Legend"], ["tooltip", "Tooltip"], ["diagnostics", "Diagnostics"]].map(([id, label]) => <option value={id} disabled={!supported(id)}>{label}</option>)}</select></label>}</>;
}
